const apacheCollage=JSON.parse(fs.readFileSync(path.join(cwd,'data/apache-collage-images.json'),'utf8'));
const names=fs.readFileSync(path.join(cwd,'original-names.txt'),'utf8').trim().split(/\r?\n/);
if(names.length!==454)throw Error('Original list must have exactly 454 names.');
const dataPath=path.join(cwd,'data','profiles.json');
const input=fs.existsSync(dataPath)?JSON.parse(fs.readFileSync(dataPath,'utf8').replace(/^\uFEFF/,'')):[];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’'‘ʻʼ\-]/g,'').replace(/\s+/g,' ').trim();
const slug=s=>norm(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
