const queuedDirectory=JSON.parse(fs.readFileSync(path.join(cwd,'data/queued-directory-entries.json'),'utf8'));
const usedSlugs=new Set();
const profiles=names.map((name,i)=>{const matches=input.filter(p=>Number(p.originalId)===i+1);if(matches.length>1)throw Error('Duplicate original ID '+(i+1));const p=matches[0];if(!p&&!partial)throw Error('Missing research for '+name);return {...(p||{overview:'Research for this entry is being assembled.',region:'Research pending',kind:'Entry',sections:[],sources:[],researchStatus:'pending'}),name,originalId:i+1,preferredName:p?.preferredName||(p?.name&&p.name!==name?p.name:undefined),added:false};});
for(const p of input.filter(p=>!p.originalId&&p.added)){if(profiles.some(x=>norm(x.name)===norm(p.name)))continue;profiles.push({...p,added:true});}
for(const p of profiles){let s=slug(p.name);if(usedSlugs.has(s))s+='-'+(p.originalId||'addition');usedSlugs.add(s);p.slug=s;p.region=p.region||'Region under review';p.kind=p.kind||'People / community';p.sections=p.sections||[];p.sources=p.sources||[];p.relatedOriginalIds=p.relatedOriginalIds||[];p.researchStatus=p.researchStatus||'source-guide';p.sources.forEach((s,i)=>{s.id=String(s.id||'s'+(i+1));s.topics=s.topics||[];s.type=s.type||'Academic / reference';if(!/^https?:\/\//.test(s.url))throw Error('Invalid URL '+p.name+' '+s.url);});const ids=new Set(p.sources.map(s=>s.id));p.sections.forEach((s,i)=>{s.sourceIds=(s.sourceIds||[]).map(String);if(!partial&&(!s.sourceIds.length||s.sourceIds.some(x=>!ids.has(x))))throw Error('Missing section citation '+p.name+' #'+i);});if(isNameOnlyOutline(p)){if(!p.added||p.originalId||p.researchStatus!=='queued'||p.researchComplete!==false||p.sources.length||p.sections.length||!p.identityVerifiedAt||!p.identificationEvidence?.length||p.identificationEvidence.some(x=>!/^https?:\/\//.test(x.url)||!x.scope))throw Error('Invalid name-only outline '+p.name);}else if(!partial&&(!p.sources.length||!p.sections.length))throw Error('Missing sources or sections '+p.name);}
for(const entry of queuedDirectory.existingNameAliases||[]){const p=profiles.find(p=>p.name===entry.existingName);if(!p)throw Error('Missing existing alias target '+entry.existingName);p.searchTerms=[...new Set([...(p.searchTerms||[]),entry.alias])];}
profiles.sort((a,b)=>norm(a.name).localeCompare(norm(b.name),'en'));
const byId=new Map(profiles.filter(p=>p.originalId).map(p=>[p.originalId,p]));
const bySlug=new Map(profiles.map(p=>[p.slug,p]));
const types=['Indigenous-led','Government','Museum / archive','Academic / reference','Reporting / interview','Other / see annotation'];
const resources=[
{id:'nk360',title:'Essential Understandings about American Indians',publisher:'Smithsonian · National Museum of the American Indian',url:'https://americanindian.si.edu/nk360/about/essential-understandings',type:'Museum / archive',topics:['Learning','Identity'],annotation:'An educational framework developed with Native communities. A useful starting point for recognizing diverse histories, perspectives, and contemporary lives.'},
{id:'bia',title:'Tribal Leaders Directory',publisher:'U.S. Bureau of Indian Affairs',url:'https://www.bia.gov/service/tribal-leaders-directory',type:'Government',topics:['Directories','Government'],annotation:'A directory of federally recognized U.S. tribal governments. Its administrative scope is narrower than the peoples, communities, and historical names included in this atlas.'},
{id:'isc',title:'First Nation Profiles',publisher:'Indigenous Services Canada',url:'https://services.sac-isc.gc.ca/fnp/main/Index.aspx?lang=eng',type:'Government',topics:['Directories','Government'],annotation:'Government profiles of individual First Nation communities in Canada. Pair these administrative records with each community’s own account.'},
{id:'inpi',title:'Atlas de los Pueblos Indígenas de México',publisher:'INPI / INALI',url:'https://atlas.inpi.gob.mx/',type:'Government',topics:['Directories','Language','Mexico'],annotation:'Spanish-language ethnographic, linguistic, audio, and geographic resources for Indigenous peoples of Mexico. Specific people-level articles appear on relevant profile pages.'},
{id:'itk',title:'About Canadian Inuit',publisher:'Inuit Tapiriit Kanatami',url:'https://itk.ca/about-canadian-inuit/',type:'Indigenous-led',topics:['Identity','Homelands','Contemporary life'],annotation:'An Inuit-led introduction to Inuit in Canada and the four regions of Inuit Nunangat. Read regional organizations alongside this national perspective.'}
];
const sourceMap=new Map();
for(const source of resources)sourceMap.set(source.url,{...source,nations:[],profileContexts:[]});
for(const p of profiles)p.sources.forEach((source,index)=>{
 if(!sourceMap.has(source.url))sourceMap.set(source.url,{...source,nations:[],profileContexts:[]});
 const previous=sourceMap.get(source.url);
 if(previous.identificationOnly&&!source.identificationOnly)sourceMap.set(source.url,{...source,nations:previous.nations,topics:previous.topics,profileContexts:previous.profileContexts});
 const entry=sourceMap.get(source.url);
 entry.nations.push({name:p.name,slug:p.slug});
 entry.topics=[...new Set([...entry.topics,...source.topics])];
 entry.profileContexts.push({profileName:p.name,profileSlug:p.slug,profileOriginalId:p.originalId||null,sourceId:source.id,profileAnchor:'source-'+(index+1),...Object.fromEntries(Object.entries(source).filter(([k])=>k!=='id'))});
});
const allSources=[...sourceMap.values()].map(s=>({...s,sourceKey:'ref-'+createHash('sha256').update(s.url).digest('hex').slice(0,16),perspectives:[...new Set([s,...s.profileContexts].flatMap(perspectiveGroups))]})).sort((a,b)=>a.publisher.localeCompare(b.publisher)||a.title.localeCompare(b.title));
const total=profiles.length,addedCount=profiles.filter(p=>p.added).length,researched=profiles.filter(p=>p.researchStatus==='researched').length;
const regionRules=[['Arctic & Alaska',/alaska|arctic|greenland|aleutian|bering/i],['Canada',/canada|british columbia|yukon|qu[eé]bec|labrador|northwest territories|newfoundland|alberta|ontario|manitoba|saskatchewan/i],['Pacific Northwest',/pacific northwest|oregon|washington|columbia river|columbia plateau|neah bay|willamette|klamath basin/i],['California',/california|san francisco|monterey|santa clara|ventura|napa|kern river/i],['Great Basin',/great basin|nevada|utah/i],['Southwest',/southwest|arizona|new mexico|four corners|colorado river/i],['Great Plains',/great plains|southern plains|oklahoma|kansas|nebraska|montana|north dakota|missouri river/i],['Great Lakes',/great lakes|wisconsin|upper michigan|indiana|mississippi valley/i],['Northeast',/northeast|new england|massachusetts|connecticut|rhode island|long island|cape cod|maine|maryland|susquehanna|delaware valley|atlantic canada/i],['Southeast',/southeast|florida|carolina|virginia|louisiana|gulf coast|georgia|mississippi/i],['Mexico',/mexico|oaxaca|sonora|chiapas|nayarit|veracruz|michoac[aá]n|baja california|campeche/i],['Central America',/central america|guatemala|belize|honduras|el salvador|nicaragua|costa rica|panama/i],['Caribbean',/caribbean|antilles|dominica/i]];
for(const p of profiles)p.regionGroups=regionRules.filter(([,rule])=>rule.test(p.region)).map(([label])=>label);
const regions=regionRules.map(([label])=>label);
const bookmarkIcon='<svg aria-hidden="true" viewBox="0 0 18 21"><path d="M3 2h12v17l-6-4-6 4z"/></svg>';
const options=(arr)=>arr.map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('');
const href=(p,base='')=>base+'nations/'+p.slug+'/';
const depth=p=>p.researchStatus==='queued'?'queued-entry':p.coverageLevel==='developed-profile'?'developed-profile':p.researchStatus;
const hasInspectedContent=p=>p.sources.some(s=>s.contentReviewedAt&&s.countsTowardMinimum!==false);
const status=p=>p.researchStatus==='queued'?'Queued for research':p.coverageLevel==='developed-profile'?(hasInspectedContent(p)?'Expanded profile':'Source inspection pending'):p.researchStatus==='researched'?'Cited overview':p.researchStatus==='pending'?'Research pending':'Source guide';
const expandedCount=profiles.filter(p=>p.coverageLevel==='developed-profile').length;
// Legacy minimum/filter fields remain twelve-source quantity measures, not adequacy gates.
const minimumSources=12;
const initialAdequacy=p=>({status:'Not assessed',reviewedAt:null,rationale:'',remainingLimits:[],...(p.initialAdequacy||{})});
const checkedSources=p=>p.sources.filter(s=>s.contentReviewedAt&&s.countsTowardMinimum!==false).length;
const minimumCollections=profiles.filter(p=>checkedSources(p)>=minimumSources).length;
const aProfiles=profiles.filter(p=>norm(p.name).startsWith('a'));
const aMinimumCollections=aProfiles.filter(p=>checkedSources(p)>=minimumSources).length;
const dateLabel=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}):'';
const latestResearchDate=profiles.map(p=>p.reviewedAt).filter(Boolean).sort().at(-1)||'2026-10-19';
