  const tabs=items.map(([key,label,url])=>`<a class="nav-tile nav-${key}${active===key?' active':''}${key==='saved'?' save-nav':''}" ${active===key?'aria-current="page"':''} href="${base}${url}"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false">${icons[key]}</svg></span><span class="nav-label">${label}</span>${key==='saved'?'<span class="saved-count" data-saved-count>0</span>':''}</a>`).join('');
