function footer(base='',extra=''){return `<footer class="site-footer wrap"><div class="footer-top"><div><div class="footer-brand">Robey’s Atlas of<br>Indigenous North America</div><span>Follow the sources. Listen to the people.</span>${extra?'':`<span class="generated-background-credit"><a href="${base}about/#archival-background">Archival portrait collage · image credits</a></span>`}</div><div class="footer-links"><a href="${base}about/">About this project</a><a href="${base}sources/">All sources</a><a href="${base}about/#photography">Photography &amp; credits</a><a href="${base}data/profiles.json" download>Download the research</a></div></div><div class="footer-note">Independent research directory · Begun October 19, 2026 · Updated ${dateLabel(latestResearchDate)} · Entries include peoples, nations, communities, historical terms, and overlapping names. Entry counts are not a count of distinct nations. Source guides are starting points for further research. Saved entries stay in this browser.</div>${extra}</footer>`;}
function document(title,description,content,base='',active='directory'){const homePage=base===''&&title==='Indigenous nations & peoples';const apache=title==='Apache'&&base==='../../';const visual=!apache&&base==='../../'?profileVisuals.byName.get(title):null;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#234d3d"><meta name="description" content="${e(description)}"><meta property="og:title" content="${e(title)} · Robey’s Atlas of Indigenous North America"><meta property="og:description" content="${e(description)}"><meta property="og:image" content="https://indigenous-nations-reading-atlas.calmlamp34.chatgpt.site/assets/robeys-atlas-brand-collage.jpg"><meta property="og:image:width" content="1280"><meta property="og:image:height" content="837"><meta property="og:image:alt" content="Robey’s Atlas of Indigenous North America brand collage"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://indigenous-nations-reading-atlas.calmlamp34.chatgpt.site/assets/robeys-atlas-brand-collage.jpg"><title>${e(title)} · Robey’s Atlas of Indigenous North America</title><link rel="icon" href="${base}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="${base}styles.css?v=home-entry-patterns-4"><link rel="stylesheet" href="${base}directory-cards.css?v=lipan-crop-9"><link rel="stylesheet" href="${base}profile-visuals.css?v=1"><link rel="stylesheet" href="${base}assets/header-navigation.css?v=home-2"><link rel="stylesheet" href="${base}assets/site-color-theme.css?v=directory-letters-4"><link rel="stylesheet" href="${base}assets/generated-background.css?v=portraits-3"><link rel="stylesheet" href="${base}assets/language-map-feature.css?v=1"><link rel="stylesheet" href="${base}assets/source-accessibility.css?v=1">${title==='The reading room'?sourceCatalogueHead(base):''}${homePage?'<link rel="stylesheet" href="assets/homepage-dividers.css?v=2"><link rel="stylesheet" href="assets/homepage-map-readability.css?v=sidebar-2">':''}${title==='The reading room'?'<link rel="stylesheet" href="../assets/reading-room-filters.css?v=scroll-2">':''}${title==='Historical maps'?'<link rel="stylesheet" href="../assets/historical-map-room.css?v=1">':''}<script defer src="${base}app.js?v=directory25${title==='The reading room'?'-sources10-access1':''}"></script><script defer src="${base}map.js"></script></head><body${apache?' class="apache-collage-page"':visual?` class="custom-profile-page" style="${e(visual.style)}"`:homePage?' class="atlas-home-page"':''}>${visual?'<div class="custom-profile-backdrop" aria-hidden="true"></div>':''}${apache?'<div class="apache-collage-backdrop" aria-hidden="true"></div>':''}${header(base,homePage?'home':active)}${content}${footer(base,homePage?homepageCredits:'')}</body></html>`;}
