write('data/catalogue-manifest.json',JSON.stringify({schemaVersion:'1.0.0',title:'Robey’s Atlas source and profile data',description:'Human-annotated links, not full source texts. Missing information is unknown, not a negative finding.',sourceCatalogue:'sources.json',sourceSchema:'source-catalogue.schema.json',profiles:'profiles.json',researchProgress:'research-progress.json',ownerReadingLeads:'owner-reading-leads.json',communityOutlineRegister:'queued-directory-entries.json',starterGuidePolicy:'starter-guide-policy.json',currentStartingCohort:'twenty-profile-batch-01.json',ownerMapLinks:'owner-map-links.json',historicalMapCatalogue:'historical-maps.json',counts:{directoryAccessPoints:profiles.length,nameOnlyOutlines:profiles.filter(isNameOnlyOutline).length,sourceUrls:allSources.length,profileSourceOccurrences:profiles.reduce((n,p)=>n+p.sources.length,0)},identifiers:{sourceKey:'Deterministic SHA-256 digest prefix of the exact source URL; record identity, not a claim that editions/mirrors are different works.',profileSlug:'Directory access-point route, which may be an alias or broader label rather than a distinct nation.'},fieldGuide:{startingGuide:'Curated existing inspected-source IDs/reasons, scope and remaining questions for a reviewed starting path; no fixed source minimum or new full-research completion claim. Legacy twelve-source threshold fields are historical quantity measures only.',entryStage:'name-only-outline means a separately findable queued entry with zero reading-source cards, zero substantive works and no completed history.',identificationEvidence:'Name/location verification provenance only. These records are separate from reading sources and do not establish historical coverage, legal status, territorial boundaries or endorsement.',existingNameAliases:'Verified longer or alternate government names can be searchable on an already represented community rather than duplicate its card.',profileContexts:'Every profile-specific source occurrence: local citation anchor, annotation, review/access scope and counting flags. Shared URLs can have different inspection limits.',contentReviewedAt:'Date of the recorded review; scope may be a selected excerpt, metadata/identity check or supporting record. Read the scope and status.',accessed:'Recorded access date, not proof of content review or current availability.',accessNotes:'Reported access conditions and inspection limits. A failed automated request is not proof of a reader paywall.',countsTowardMinimum:'False excludes a supporting or identity record. Absence is a legacy quantity convention, not proof of adequacy or full-work inspection.',quantityRule:'Recorded substantive quantity uses contentReviewedAt and countsTowardMinimum !== false; completeness, initialAdequacy and community review are separate.',perspectives:'Navigation groups derived from the recorded source type; mixed types can appear in several groups. Original type/annotation remain authoritative for scope.',reuse:'Original works and images keep their individual terms. No blanket source-text/image permission is granted by this catalogue.'}},null,2));
write('data/source-catalogue.schema.json',JSON.stringify({$schema:'https://json-schema.org/draft/2020-12/schema',$id:'https://indigenous-nations-reading-atlas.calmlamp34.chatgpt.site/data/source-catalogue.schema.json',title:'Atlas source catalogue version1',type:'array',items:{type:'object',required:['sourceKey','url','title','publisher','profileContexts','perspectives'],properties:{sourceKey:{type:'string',pattern:'^ref-[a-f0-9]{16}$'},url:{type:'string',format:'uri'},title:{type:'string'},publisher:{type:'string'},type:{type:'string'},perspectives:{type:'array',items:{type:'string'}},profileContexts:{type:'array',items:{type:'object',required:['profileName','profileSlug','sourceId','profileAnchor'],properties:{profileName:{type:'string'},profileSlug:{type:'string'},sourceId:{type:'string'},profileAnchor:{type:'string'},contentReviewedAt:{type:['string','null']},countsTowardMinimum:{type:'boolean'},identificationOnly:{type:'boolean'}},additionalProperties:true}}},additionalProperties:true}},null,2));
